"use strict";(self.webpackChunkwiki_es=self.webpackChunkwiki_es||[]).push([["83828"],{67685(e,a,n){n.r(a),n.d(a,{metadata:()=>i,default:()=>u,frontMatter:()=>r,contentTitle:()=>t,toc:()=>d,assets:()=>l});var i=JSON.parse('{"id":"Sensor/Wio_Terminal/Application/Embedded_ML/Projects_based_Edge_Impulse/es_Wio-Terminal-TinyML-EI-6","title":"Detecci\xf3n de anomal\xedas para Mantenimiento Predictivo","description":"Detecci\xf3n de anomal\xedas para Mantenimiento Predictivo","source":"@site/docs/Sensor/Wio_Terminal/Application/Embedded_ML/Projects_based_Edge_Impulse/es_Wio-Terminal-TinyML-EI-6.md","sourceDirName":"Sensor/Wio_Terminal/Application/Embedded_ML/Projects_based_Edge_Impulse","slug":"/Wio-Terminal-TinyML-EI-6","permalink":"/es/Wio-Terminal-TinyML-EI-6","draft":false,"unlisted":false,"editUrl":"https://github.com/Seeed-Studio/wiki-documents/blob/docusaurus-version/sites/es/docs/Sensor/Wio_Terminal/Application/Embedded_ML/Projects_based_Edge_Impulse/es_Wio-Terminal-TinyML-EI-6.md","tags":[],"version":"current","lastUpdatedBy":"jianjing Huang","lastUpdatedAt":1675036800000,"frontMatter":{"description":"Detecci\xf3n de anomal\xedas para Mantenimiento Predictivo","title":"Detecci\xf3n de anomal\xedas para Mantenimiento Predictivo","keywords":["Wio_terminal","Embedded_ML","Projects_based_Edge_Impulse"],"image":"https://files.seeedstudio.com/wiki/wiki-platform/S-tempor.png","slug":"/Wio-Terminal-TinyML-EI-6","last_update":{"date":"1/30/2023","author":"jianjing Huang"},"createdAt":"2025-09-03","updatedAt":"2025-10-11","url":"https://wiki.seeedstudio.com/es/Wio-Terminal-TinyML-EI-6/"},"sidebar":"esSidebar","previous":{"title":"Distinguir Bebidas","permalink":"/es/Wio-Terminal-TinyML-EI-5"},"next":{"title":"TensorFlow Lite Micro Getting Started","permalink":"/es/Wio-Terminal-TinyML-TFLM-1"}}'),o=n(31085),s=n(71184);let r={description:"Detecci\xf3n de anomal\xedas para Mantenimiento Predictivo",title:"Detecci\xf3n de anomal\xedas para Mantenimiento Predictivo",keywords:["Wio_terminal","Embedded_ML","Projects_based_Edge_Impulse"],image:"https://files.seeedstudio.com/wiki/wiki-platform/S-tempor.png",slug:"/Wio-Terminal-TinyML-EI-6",last_update:{date:"1/30/2023",author:"jianjing Huang"},createdAt:"2025-09-03",updatedAt:"2025-10-11",url:"https://wiki.seeedstudio.com/es/Wio-Terminal-TinyML-EI-6/"},t="Detecci\xf3n de Anomal\xedas con Edge Impulse en Wio Terminal para Mantenimiento Predictivo",l={},d=[{value:"Detecci\xf3n de anomal\xedas y mantenimiento predictivo en pocas palabras",id:"detecci\xf3n-de-anomal\xedas-y-mantenimiento-predictivo-en-pocas-palabras",level:2},{value:"Recopilaci\xf3n de datos y entrenamiento del modelo",id:"recopilaci\xf3n-de-datos-y-entrenamiento-del-modelo",level:2},{value:"Despliegue y pruebas",id:"despliegue-y-pruebas",level:2},{value:"Utilizando la nueva versi\xf3n de la plataforma Blynk IoT",id:"utilizando-la-nueva-versi\xf3n-de-la-plataforma-blynk-iot",level:2},{value:"Referencia",id:"referencia",level:2}];function c(e){let a={a:"a",code:"code",h1:"h1",h2:"h2",header:"header",li:"li",p:"p",pre:"pre",ul:"ul",...(0,s.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(a.header,{children:(0,o.jsx)(a.h1,{id:"detecci\xf3n-de-anomal\xedas-con-edge-impulse-en-wio-terminal-para-mantenimiento-predictivo",children:"Detecci\xf3n de Anomal\xedas con Edge Impulse en Wio Terminal para Mantenimiento Predictivo"})}),"\n",(0,o.jsx)("div",{align:"center",children:(0,o.jsx)("img",{src:"https://files.seeedstudio.com/wiki/Wio-Terminal-TinyML-EI-6/full-Time-0_19_2725-1536x864.png"})}),"\n",(0,o.jsx)(a.p,{children:"En este proyecto, utilizaremos datos del aceler\xf3metro integrado de Wio Terminal, realizaremos detecci\xf3n de anomal\xedas en el dispositivo y luego enviaremos los datos a Blynk Edgent Cloud."}),"\n",(0,o.jsx)(a.p,{children:"Anomal\xedas. O espec\xedficamente detecci\xf3n de anomal\xedas para mantenimiento predictivo. Vamos a utilizar datos del aceler\xf3metro integrado de Wio Terminal, realizar inferencia de modelo de red neuronal y detecci\xf3n de anomal\xedas en el dispositivo y luego enviar datos a la nueva versi\xf3n de la plataforma IoT Blynk con una gran cantidad de nuevas caracter\xedsticas, que es totalmente compatible con Wio Terminal."}),"\n",(0,o.jsx)(a.p,{children:"Para el tutorial completo y demostraci\xf3n en video, echa un vistazo al video que lo acompa\xf1a:"}),"\n",(0,o.jsx)("div",{class:"video-container",children:(0,o.jsx)("iframe",{width:"560",height:"315",src:"https://www.youtube.com/embed/gXs-h3eeT1U",frameborder:"0",allow:"accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture",allowfullscreen:!0})}),"\n",(0,o.jsx)(a.p,{children:"Eso es QU\xc9, ahora para la parte de C\xd3MO, comencemos con un ejemplo que podr\xeda ser m\xe1s familiar."}),"\n",(0,o.jsx)(a.h2,{id:"detecci\xf3n-de-anomal\xedas-y-mantenimiento-predictivo-en-pocas-palabras",children:"Detecci\xf3n de anomal\xedas y mantenimiento predictivo en pocas palabras"}),"\n",(0,o.jsx)(a.p,{children:"Si entrenas un modelo simple de reconocimiento de im\xe1genes para reconocer digamos 5 clases diferentes de animales (tigre, elefante, oso, serpiente y jirafa) y luego le das una imagen de una persona, har\xe1 una predicci\xf3n lo mejor que pueda y posiblemente diga que es un elefante. Cue las risas de la gente com\xfan, que realmente no entiende mucho sobre el funcionamiento interno de este modelo particular y la visi\xf3n por computadora en general."}),"\n",(0,o.jsx)(a.p,{children:'Por supuesto, el modelo no hizo nada malo \u2013 proces\xf3 la imagen, calcul\xf3 las caracter\xedsticas presentes y luego produjo el resultado de clasificaci\xf3n basado en estas caracter\xedsticas. Aunque si graficamos las caracter\xedsticas de las clases y las agrupamos, ver\xedamos que idealmente las caracter\xedsticas de la imagen humana est\xe1n lejos de cualquier grupo de clases y por lo tanto representan un "valor at\xedpico".'}),"\n",(0,o.jsx)("div",{align:"center",children:(0,o.jsx)("img",{src:"https://files.seeedstudio.com/wiki/Wio-Terminal-TinyML-EI-6/knowing_all_about_outliers_in_machine_learning_sample_points_in_green_are_near_to_each_other.png"})}),"\n",(0,o.jsx)(a.p,{children:"Lo cual por supuesto podr\xeda ser solo una imagen muy extra\xf1a de uno de los animales, pero en la mayor\xeda de los casos es mucho m\xe1s probable que sea un objeto que el modelo no fue entrenado para reconocer."}),"\n",(0,o.jsx)(a.p,{children:'Para tareas de visi\xf3n por computadora y reconocimiento de voz a menudo tenemos una clase de "fondo" para lidiar con este problema, que b\xe1sicamente representa cualquier cosa que no sean las clases de inter\xe9s. En algunas situaciones, realmente solo queremos que nuestro modelo sea capaz de interpretar todos los datos como "normal" y "anormal". No importa cu\xe1les son las caracter\xedsticas exactas de "anormal" \u2013 pueden ser muy diferentes, lo importante es que si se detecta la clase "anormal", se necesitan implementar algunas medidas. Lo que describ\xed ahora es la premisa detr\xe1s del uso de Aprendizaje Autom\xe1tico para mantenimiento predictivo. Monitoreamos el estado del dispositivo, ya sea un aire acondicionado, bomba de agua u otra maquinaria con sensores y bas\xe1ndonos en el perfil de operaci\xf3n "normal" conocida, tratamos de detectar cu\xe1ndo algo va LIGERAMENTE mal, antes de que vaya SERIAMENTE mal.'}),"\n",(0,o.jsx)(a.h2,{id:"recopilaci\xf3n-de-datos-y-entrenamiento-del-modelo",children:"Recopilaci\xf3n de datos y entrenamiento del modelo"}),"\n",(0,o.jsx)(a.p,{children:"Para este proyecto instal\xe9 Wio Terminal en una bomba de agua en el patio exterior de nuestra oficina, que tiene algunas plantas y peces."}),"\n",(0,o.jsx)("div",{align:"center",children:(0,o.jsx)("img",{src:"https://files.seeedstudio.com/wiki/Wio-Terminal-TinyML-EI-6/full-Time-0_04_2007-1536x864.png"})}),"\n",(0,o.jsx)(a.p,{children:"Luego recopil\xe9 dos categor\xedas de muestras: inactivo y operaci\xf3n normal, y entren\xe9 un modelo simple para reconocer estas dos bas\xe1ndose en la salida del bloque de procesamiento de Caracter\xedsticas Espectrales."}),"\n",(0,o.jsx)("div",{align:"center",children:(0,o.jsx)("img",{src:"https://files.seeedstudio.com/wiki/Wio-Terminal-TinyML-EI-6/image-1.png"})}),"\n",(0,o.jsx)("div",{align:"center",children:(0,o.jsx)("img",{src:"https://files.seeedstudio.com/wiki/Wio-Terminal-TinyML-EI-6/image-2.png"})}),"\n",(0,o.jsx)(a.p,{children:"Para los par\xe1metros exactos de los bloques de procesamiento y aprendizaje, puedes echar un vistazo a la versi\xf3n p\xfablica del proyecto que compart\xed. El \xfanico ajuste significativo que hice fue cambiar el filtro de bajo a alto, lo que hizo que las caracter\xedsticas de diferentes clases fueran m\xe1s prominentes. Distinguir entre operaci\xf3n inactiva y normal de la bomba por supuesto result\xf3 ser realmente f\xe1cil. La tarea m\xe1s desafiante fue la detecci\xf3n de mal funcionamiento. Para simular un mal funcionamiento sacar\xeda la bomba de agua del tanque, esto b\xe1sicamente llevaba a que los niveles de sonido y vibraci\xf3n disminuyeran."}),"\n",(0,o.jsx)("div",{align:"center",children:(0,o.jsx)("img",{src:"https://files.seeedstudio.com/wiki/Wio-Terminal-TinyML-EI-6/full-Time-0_19_2725-1536x864.png"})}),"\n",(0,o.jsx)(a.p,{children:"Observando la muestra de mal funcionamiento, en el explorador de caracter\xedsticas en los ejes accX RMS, accY RMS y accZ RMS, vemos que est\xe1 a medio camino entre las muestras de operaci\xf3n inactiva y normal."}),"\n",(0,o.jsx)("div",{align:"center",children:(0,o.jsx)("img",{src:"https://files.seeedstudio.com/wiki/Wio-Terminal-TinyML-EI-6/image-3-1536x906.png"})}),"\n",(0,o.jsx)(a.p,{children:"Podemos usar esto a nuestro favor entrenando una nueva (segunda) red que crea grupos alrededor de datos que hemos visto antes, y compara los datos entrantes contra estos grupos. Si la distancia de un grupo es demasiado grande, la muestra es marcada como una anomal\xeda."}),"\n",(0,o.jsx)(a.p,{children:"Despu\xe9s de prueba y error encontr\xe9 que un conteo de grupos muy bajo y un umbral de distancia de 0.5 funciona mejor para la detecci\xf3n de anomal\xedas, pero esto es muy espec\xedfico del caso y depende de tus datos. Una cosa que ayud\xf3 a aumentar la precisi\xf3n fue fijar Wio Terminal en la bomba de agua firmemente con pegamento; para un dispositivo real puedes usar tornillos. Antes de fijarlo firmemente, Wio Terminal se tambaleaba aleatoriamente, lo que introduc\xeda demasiado ruido en las muestras de operaci\xf3n normal."}),"\n",(0,o.jsx)(a.h2,{id:"despliegue-y-pruebas",children:"Despliegue y pruebas"}),"\n",(0,o.jsx)(a.p,{children:"Despu\xe9s de que el modelo es entrenado y probado usando el modo de clasificaci\xf3n en vivo, es hora de desplegarlo de vuelta al dispositivo. Compilamos y descargamos la biblioteca de Arduino, la extraemos a la carpeta de bibliotecas de Arduino y luego modificamos el sketch nano33_ble_sense_accelerometer para que coincida con el aceler\xf3metro que tenemos en Wio Terminal. Para una prueba simple usamos la pantalla LCD que se ilumina en rojo si se detecta una anomal\xeda."}),"\n",(0,o.jsx)(a.pre,{children:(0,o.jsx)(a.code,{className:"language-cpp",children:'#define ANOMALY_THRESHOLD 0.5\n\n/* Includes ---------------------------------------------------------------- */\n#include <wio_anomaly_detection_inference.h>\n#include"LIS3DHTR.h"\n#include"TFT_eSPI.h"\n\nTFT_eSPI tft;\nLIS3DHTR<TwoWire> lis;\n\n/* Constant defines -------------------------------------------------------- */\n#define CONVERT_G_TO_MS2    9.80665f\n\n/* Private variables ------------------------------------------------------- */\nstatic bool debug_nn = false; // Set this to true to see e.g. features generated from the raw signal\n\n/**\n* @brief      Arduino setup function\n*/\nvoid setup()\n{\n    // put your setup code here, to run once:\n    Serial.begin(115200);\n    //while (!Serial) {delay(10);}\n    \n    Serial.println("Edge Impulse Inferencing Demo");\n    \n    tft.begin();\n    tft.setRotation(3);\n    \n    lis.begin(Wire1);\n \n    if (!lis.available()) {\n    Serial.println("Failed to initialize IMU!");\n    while (1);\n    }\n    else {\n        ei_printf("IMU initialized\\r\\n");\n    }\n    lis.setOutputDataRate(LIS3DHTR_DATARATE_100HZ); // Setting output data rage to 25Hz, can be set up tp 5kHz \n    lis.setFullScaleRange(LIS3DHTR_RANGE_16G); // Setting scale range to 2g, select from 2,4,8,16g\n   \n\n    if (EI_CLASSIFIER_RAW_SAMPLES_PER_FRAME != 3) {\n        ei_printf("ERR: EI_CLASSIFIER_RAW_SAMPLES_PER_FRAME should be equal to 3 (the 3 sensor axes)\\n");\n        return;\n    }\n}\n\n/**\n* @brief      Printf function uses vsnprintf and output using Arduino Serial\n*\n* @param[in]  format     Variable argument list\n*/\nvoid ei_printf(const char *format, ...) {\n   static char print_buf[1024] = { 0 };\n\n   va_list args;\n   va_start(args, format);\n   int r = vsnprintf(print_buf, sizeof(print_buf), format, args);\n   va_end(args);\n\n   if (r > 0) {\n       Serial.write(print_buf);\n   }\n}\n\n/**\n* @brief      Get data and run inferencing\n*\n* @param[in]  debug  Get debug info if true\n*/\nvoid loop()\n{\n\n    ei_printf("Sampling...\\n");\n\n    // Allocate a buffer here for the values we\'ll read from the IMU\n    float buffer[EI_CLASSIFIER_DSP_INPUT_FRAME_SIZE] = { 0 };\n\n    for (size_t ix = 0; ix < EI_CLASSIFIER_DSP_INPUT_FRAME_SIZE; ix += 3) {\n        // Determine the next tick (and then sleep later)\n        uint64_t next_tick = micros() + (EI_CLASSIFIER_INTERVAL_MS * 1000);\n\n        lis.getAcceleration(&buffer[ix], &buffer[ix+1], &buffer[ix + 2]);\n        buffer[ix + 0] *= CONVERT_G_TO_MS2;\n        buffer[ix + 1] *= CONVERT_G_TO_MS2;\n        buffer[ix + 2] *= CONVERT_G_TO_MS2;\n\n        delayMicroseconds(next_tick - micros());\n    }\n\n    // Turn the raw buffer in a signal which we can the classify\n    signal_t signal;\n    int err = numpy::signal_from_buffer(buffer, EI_CLASSIFIER_DSP_INPUT_FRAME_SIZE, &signal);\n    if (err != 0) {\n        ei_printf("Failed to create signal from buffer (%d)\\n", err);\n        return;\n    }\n\n    // Run the classifier\n    ei_impulse_result_t result = { 0 };\n\n    err = run_classifier(&signal, &result, debug_nn);\n    if (err != EI_IMPULSE_OK) {\n        ei_printf("ERR: Failed to run classifier (%d)\\n", err);\n        return;\n    }\n\n    // print the predictions\n    ei_printf("Predictions ");\n    ei_printf("(DSP: %d ms., Classification: %d ms., Anomaly: %d ms.)",\n        result.timing.dsp, result.timing.classification, result.timing.anomaly);\n    ei_printf(": \\n");\n    for (size_t ix = 0; ix < EI_CLASSIFIER_LABEL_COUNT; ix++) {\n        ei_printf("    %s: %.5f\\n", result.classification[ix].label, result.classification[ix].value);\n    }\n#if EI_CLASSIFIER_HAS_ANOMALY == 1\n    ei_printf("    anomaly score: %.3f\\n", result.anomaly);\n\n  if (result.anomaly > ANOMALY_THRESHOLD)\n  {       \n    tft.fillScreen(TFT_RED);\n    tft.setFreeFont(&FreeSansBoldOblique12pt7b);\n    tft.drawString("Anomaly detected", 20, 80);\n    delay(1000);\n    tft.fillScreen(TFT_WHITE);\n  }\n    \n#endif\n}\n\n#if !defined(EI_CLASSIFIER_SENSOR) || EI_CLASSIFIER_SENSOR != EI_CLASSIFIER_SENSOR_ACCELEROMETER\n#error "Invalid model for current sensor"\n#endif\n'})}),"\n",(0,o.jsx)(a.p,{children:"Por supuesto, para una aplicaci\xf3n real, este tipo de notificaci\xf3n probablemente no va a funcionar, porque no hay una persona que la vigile constantemente."}),"\n",(0,o.jsx)(a.h2,{id:"utilizando-la-nueva-versi\xf3n-de-la-plataforma-blynk-iot",children:"Utilizando la nueva versi\xf3n de la plataforma Blynk IoT"}),"\n",(0,o.jsx)(a.p,{children:"Para hacer \xfatil esta demostraci\xf3n, vamos a usar la plataforma Blynk IoT."}),"\n",(0,o.jsx)("div",{align:"center",children:(0,o.jsx)("img",{src:"https://files.seeedstudio.com/wiki/Wio-Terminal-TinyML-EI-6/b641e2030c1c47fbc7161c98a7e5d998.jpg"})}),"\n",(0,o.jsx)(a.p,{children:"La plataforma Blynk IoT incluye caracter\xedsticas como un panel web para monitorear dispositivos, gestionar qui\xe9n accede a los datos, un administrador de Wi-Fi para un procedimiento de configuraci\xf3n f\xe1cil, un nuevo enfoque para la creaci\xf3n de modelos de dispositivos y otros."}),"\n",(0,o.jsx)(a.p,{children:"Ve a blynk.cloud, registra una cuenta o crea una nueva. Luego crea una nueva plantilla \u2013 las plantillas son modelos digitales del dispositivo que pueden ser heredados por m\xfaltiples dispositivos con funcionalidad similar. El poder de las plantillas es una actualizaci\xf3n instant\xe1nea del modelo de datos del dispositivo sin importar el tama\xf1o de tu flota de dispositivos."}),"\n",(0,o.jsx)(a.p,{children:"Elige Arduino Uno como hardware y Wi-Fi como tipo de conexi\xf3n. Luego completa las pesta\xf1as Datastreams y Dashboard como en las siguientes capturas de pantalla y guarda los cambios."}),"\n",(0,o.jsx)("div",{align:"center",children:(0,o.jsx)("img",{src:"https://files.seeedstudio.com/wiki/Wio-Terminal-TinyML-EI-6/image-4-1536x551.png"})}),"\n",(0,o.jsx)("div",{align:"center",children:(0,o.jsx)("img",{src:"https://files.seeedstudio.com/wiki/Wio-Terminal-TinyML-EI-6/image-5.png"})}),"\n",(0,o.jsx)(a.p,{children:"No estamos usando las pesta\xf1as Metadata o Events en este proyecto. El prop\xf3sito principal de los componentes principales de la plantilla del dispositivo:"}),"\n",(0,o.jsxs)(a.ul,{children:["\n",(0,o.jsx)(a.li,{children:"Metadata \u2013 datos adicionales sobre el dispositivo que puedes configurar."}),"\n",(0,o.jsx)(a.li,{children:"Datastreams \u2013 una entidad para definir los datos que fluyen hacia y desde el dispositivo. En general, es muy similar a los Pines Virtuales (que tambi\xe9n se pueden usar)."}),"\n",(0,o.jsx)(a.li,{children:"Events \u2013 una lista de alertas y notificaciones importantes."}),"\n",(0,o.jsx)(a.li,{children:"Web Dashboard \u2013 Un conjunto de Widgets en la aplicaci\xf3n Web"}),"\n",(0,o.jsx)(a.li,{children:"Mobile Dashboard \u2013 Un conjunto de Widgets en la aplicaci\xf3n M\xf3vil"}),"\n"]}),"\n",(0,o.jsx)(a.p,{children:"Crea un nuevo dispositivo en la pesta\xf1a My Devices \u2013 elige la plantilla que has creado y dale un nombre \xfanico."}),"\n",(0,o.jsx)(a.p,{children:"Ahora la interfaz web est\xe1 lista para recibir los datos de nuestro dispositivo. Descarga el sketch de ejemplo del repositorio de sketches de ejemplo de Seeed Wio Terminal \u2013 adem\xe1s del archivo principal del sketch tambi\xe9n contiene archivos auxiliares, donde se encuentra el c\xf3digo del administrador de Wi-Fi. En el archivo principal del sketch, el c\xf3digo de recolecci\xf3n de datos/procesamiento de datos/inferencia que usamos para probar con la pantalla LCD fue movido a la funci\xf3n run_inference(). El ID de clase de la clase con mayor confianza (si la confianza est\xe1 por encima del umbral establecido) se guarda dentro de la variable global best_result y junto con los datos de los sensores de luz y sonido se env\xeda al servidor Blynk a intervalos peri\xf3dicos. Recuerda cambiar BLYNK_TEMPLATE_ID y BLYNK_DEVICE_NAME por los de tu plantilla de dispositivo."}),"\n",(0,o.jsx)("div",{align:"center",children:(0,o.jsx)("img",{src:"https://files.seeedstudio.com/wiki/Wio-Terminal-TinyML-EI-6/image-6.png"})}),"\n",(0,o.jsx)(a.p,{children:"Despu\xe9s de subir el c\xf3digo a Wio Terminal, crear\xe1 un punto de acceso, al cual puedes conectarte con tu tel\xe9fono. Al conectarte ser\xe1s autom\xe1ticamente redirigido a una p\xe1gina de configuraci\xf3n simple, donde necesitas ingresar tus credenciales de WiFi, tu token de API (puedes encontrarlo haciendo clic en tu dispositivo en la pesta\xf1a My Devices y luego yendo a Device Info) y luego hacer clic en Connect. Entonces Wio Terminal se conectar\xe1 a la red WiFi y al servidor en la nube de Blynk y comenzar\xe1 a enviar los datos. Puedes presionar en el dispositivo en la pesta\xf1a My Devices y ver los gr\xe1ficos bonitos y el mensaje de estado. Puedes ver los resultados de la prueba hacia el final del video."}),"\n",(0,o.jsx)(a.p,{children:"Obviamente, el mismo enfoque se puede aplicar para detectar irregularidades en la operaci\xf3n de otra maquinaria \u2013 podemos usar el aceler\xf3metro para pr\xe1cticamente todo lo que tenga partes m\xf3viles, ya que estas producen vibraci\xf3n que podemos medir. Si el dispositivo emite sonidos audibles, tambi\xe9n podemos usar el micr\xf3fono. Una combinaci\xf3n de sensores podr\xeda funcionar incluso mejor. \xbfHay otras buenas aplicaciones donde se pueda usar el mantenimiento predictivo? \xa1Escribe tus ideas en los comentarios! \xa1Espero que este art\xedculo y video hayan sido \xfatiles para ti!"}),"\n",(0,o.jsx)(a.h2,{id:"referencia",children:"Referencia"}),"\n",(0,o.jsxs)(a.ul,{children:["\n",(0,o.jsxs)(a.li,{children:["\n",(0,o.jsx)(a.p,{children:(0,o.jsx)(a.a,{href:"https://studio.edgeimpulse.com/public/31205/latest",children:"Proyecto p\xfablico de Edge Impulse"})}),"\n"]}),"\n",(0,o.jsxs)(a.li,{children:["\n",(0,o.jsx)(a.p,{children:(0,o.jsx)(a.a,{href:"https://github.com/Seeed-Studio/Seeed_Arduino_Sketchbook/tree/master/examples/WioTerminal_TinyML_5_Anomaly_Detection",children:"Github del proyecto"})}),"\n"]}),"\n"]})]})}function u(e={}){let{wrapper:a}={...(0,s.R)(),...e.components};return a?(0,o.jsx)(a,{...e,children:(0,o.jsx)(c,{...e})}):c(e)}},71184(e,a,n){n.d(a,{R:()=>r,x:()=>t});var i=n(14041);let o={},s=i.createContext(o);function r(e){let a=i.useContext(s);return i.useMemo(function(){return"function"==typeof e?e(a):{...a,...e}},[a,e])}function t(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:r(e.components),i.createElement(s.Provider,{value:a},e.children)}}}]);